import React from "react";
import { Card, Row, Col, Badge } from "react-bootstrap";

const TripAnalytics = ({ trips = [] }) => {
  // Dummy calculations
  const totalTrips = trips.length;
  const liveTrips = trips.filter((t) => t.status === "LIVE").length;
  const completedTrips = trips.filter((t) => t.status === "COMPLETED").length;
  const totalDistance = trips.reduce((sum, t) => sum + (t.analytics?.distance || 0), 0);
  const totalDuration = trips.reduce((sum, t) => sum + (t.analytics?.duration || 0), 0);
  const uniqueVehicles = new Set(trips.map((t) => t.vehicle?.name)).size;
  const uniqueDrivers = new Set(trips.map((t) => t.driver?.name)).size;

  return (
    <Card>
      <Card.Header>
        <h5 className="mb-0">Trip Analytics</h5>
      </Card.Header>
      <Card.Body>
        <Row className="mb-2">
          <Col xs={6} className="mb-2">
            <Badge bg="primary" className="p-2 w-100">Total Trips: {totalTrips}</Badge>
          </Col>
          <Col xs={6} className="mb-2">
            <Badge bg="success" className="p-2 w-100">Live Trips: {liveTrips}</Badge>
          </Col>
        </Row>
        <Row className="mb-2">
          <Col xs={6} className="mb-2">
            <Badge bg="secondary" className="p-2 w-100">Completed Trips: {completedTrips}</Badge>
          </Col>
          <Col xs={6} className="mb-2">
            <Badge bg="info" className="p-2 w-100">Unique Vehicles: {uniqueVehicles}</Badge>
          </Col>
        </Row>
        <Row className="mb-2">
          <Col xs={6} className="mb-2">
            <Badge bg="warning" text="dark" className="p-2 w-100">Unique Drivers: {uniqueDrivers}</Badge>
          </Col>
          <Col xs={6} className="mb-2">
            <Badge bg="dark" className="p-2 w-100">Total Distance: {totalDistance} km</Badge>
          </Col>
        </Row>
        <Row>
          <Col xs={12}>
            <Badge bg="light" text="dark" className="p-2 w-100">Total Duration: {totalDuration} hrs</Badge>
          </Col>
        </Row>
      </Card.Body>
    </Card>
  );
};

export default TripAnalytics; 