const UserActivity = () => {
  const [activity, setActivity] = useState(dummyActivity);
  const [userFilter, setUserFilter] = useState("");
  const [actionFilter, setActionFilter] = useState("ALL");
  const [statusFilter, setStatusFilter] = useState("ALL");
  const [dateFilter, setDateFilter] = useState("");

  const filteredActivity = activity.filter((item) => {
    const matchesUser =
      !userFilter ||
      item.username.toLowerCase().includes(userFilter.toLowerCase()) ||
      item.fullName.toLowerCase().includes(userFilter.toLowerCase());

    const matchesAction =
      actionFilter === "ALL" || item.action === actionFilter;
    const matchesStatus =
      statusFilter === "ALL" || item.status === statusFilter;

    const matchesDate = !dateFilter || item.timestamp.startsWith(dateFilter);

    return matchesUser && matchesAction && matchesStatus && matchesDate;
  });

  const getActionBadge = (action) => {
    const variants = {
      LOGIN: "success",
      LOGOUT: "info",
      LOGIN_FAILED: "danger",
      USER_CREATE: "primary",
      USER_UPDATE: "warning",
      VEHICLE_VIEW: "secondary",
      TEAM_UPDATE: "info",
      PERMISSION_UPDATE: "warning",
    };
    return (
      <Badge bg={variants[action] || "secondary"}>
        {action.replace("_", " ")}
      </Badge>
    );
  };

  const getStatusBadge = (status) => {
    const variants = {
      SUCCESS: "success",
      FAILED: "danger",
      PENDING: "warning",
    };
    return <Badge bg={variants[status] || "secondary"}>{status}</Badge>;
  };

  const getUniqueActions = () => {
    return [...new Set(activity.map((item) => item.action))];
  };

  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h2>User Activity Log</h2>
        <Button variant="outline-primary">
          <ListAltIcon className="me-2" />
          Export Logs
        </Button>
      </div>

      {/* Filters */}
      <Card className="mb-4">
        <Card.Body>
          <Row>
            <Col md={3}>
              <Form.Group>
                <Form.Label>Search User</Form.Label>
                <Form.Control
                  type="text"
                  placeholder="Search by username or name..."
                  value={userFilter}
                  onChange={(e) => setUserFilter(e.target.value)}
                />
              </Form.Group>
            </Col>
            <Col md={3}>
              <Form.Group>
                <Form.Label>Action Type</Form.Label>
                <Form.Select
                  value={actionFilter}
                  onChange={(e) => setActionFilter(e.target.value)}
                >
                  <option value="ALL">All Actions</option>
                  {getUniqueActions().map((action) => (
                    <option key={action} value={action}>
                      {action.replace("_", " ")}
                    </option>
                  ))}
                </Form.Select>
              </Form.Group>
            </Col>
            <Col md={3}>
              <Form.Group>
                <Form.Label>Status</Form.Label>
                <Form.Select
                  value={statusFilter}
                  onChange={(e) => setStatusFilter(e.target.value)}
                >
                  <option value="ALL">All Status</option>
                  <option value="SUCCESS">Success</option>
                  <option value="FAILED">Failed</option>
                  <option value="PENDING">Pending</option>
                </Form.Select>
              </Form.Group>
            </Col>
            <Col md={3}>
              <Form.Group>
                <Form.Label>Date</Form.Label>
                <Form.Control
                  type="date"
                  value={dateFilter}
                  onChange={(e) => setDateFilter(e.target.value)}
                />
              </Form.Group>
            </Col>
          </Row>
        </Card.Body>
      </Card>

      {/* Activity Stats */}
      <Row className="mb-4">
        <Col md={3}>
          <Card className="text-center">
            <Card.Body>
              <h4 className="text-success">
                {activity.filter((a) => a.status === "SUCCESS").length}
              </h4>
              <small className="text-muted">Successful Actions</small>
            </Card.Body>
          </Card>
        </Col>
        <Col md={3}>
          <Card className="text-center">
            <Card.Body>
              <h4 className="text-danger">
                {activity.filter((a) => a.status === "FAILED").length}
              </h4>
              <small className="text-muted">Failed Actions</small>
            </Card.Body>
          </Card>
        </Col>
        <Col md={3}>
          <Card className="text-center">
            <Card.Body>
              <h4 className="text-primary">
                {new Set(activity.map((a) => a.userId)).size}
              </h4>
              <small className="text-muted">Active Users</small>
            </Card.Body>
          </Card>
        </Col>
        <Col md={3}>
          <Card className="text-center">
            <Card.Body>
              <h4 className="text-info">{activity.length}</h4>
              <small className="text-muted">Total Activities</small>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Activity Table */}
      <Card>
        <Card.Body>
          <Table responsive striped hover>
            <thead>
              <tr>
                <th>User</th>
                <th>Action</th>
                <th>Description</th>
                <th>Status</th>
                <th>IP Address</th>
                <th>Location</th>
                <th>Timestamp</th>
              </tr>
            </thead>
            <tbody>
              {filteredActivity.map((item) => (
                <tr key={item.id}>
                  <td>
                    <div>
                      <strong>{item.fullName}</strong>
                      <br />
                      <small className="text-muted">@{item.username}</small>
                    </div>
                  </td>
                  <td>{getActionBadge(item.action)}</td>
                  <td>
                    <div>
                      {item.description}
                      <br />
                      <small className="text-muted">{item.userAgent}</small>
                    </div>
                  </td>
                  <td>{getStatusBadge(item.status)}</td>
                  <td>
                    <code>{item.ipAddress}</code>
                  </td>
                  <td>
                    <div>
                      <RoomIcon className="me-1" />
                      {item.location}
                    </div>
                  </td>
                  <td>
                    <div>
                      <CalendarTodayIcon className="me-1" />
                      {new Date(item.timestamp).toLocaleDateString()}
                      <br />
                      <small className="text-muted">
                        <AccessTimeIcon className="me-1" />
                        {new Date(item.timestamp).toLocaleTimeString()}
                      </small>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </Table>
        </Card.Body>
      </Card>
    </div>
  );
};

