import React, { useState } from "react";
import { Card, Button, ListGroup } from "react-bootstrap";

const VehicleForecast = ({ vehicles = [], onForecast }) => {
  const [forecast, setForecast] = useState(null);

  const handleForecast = () => {
    // Dummy forecast: count available vehicles
    const available = vehicles.filter((v) => v.status === "AVAILABLE").length;
    const result = `Available vehicles: ${available} / ${vehicles.length}`;
    setForecast(result);
    onForecast && onForecast(result);
  };

  return (
    <Card>
      <Card.Header>
        <h5 className="mb-0">Vehicle Availability Forecast</h5>
      </Card.Header>
      <Card.Body>
        <ListGroup className="mb-3">
          {vehicles.map((v) => (
            <ListGroup.Item key={v.id}>
              <strong>{v.name}</strong> <span className="text-muted">({v.status})</span>
            </ListGroup.Item>
          ))}
        </ListGroup>
        <Button variant="info" onClick={handleForecast}>
          Forecast Availability
        </Button>
        {forecast && <div className="mt-3"><strong>{forecast}</strong></div>}
      </Card.Body>
    </Card>
  );
};

export default VehicleForecast; 