import React, { useState } from "react";
import { Card, Table, Button, Alert } from "react-bootstrap";
import { ROLE_PERMISSIONS, PERMISSIONS, ROLES } from "../../routes/permissions";
import { authService } from "../../services";

const allRoles = Object.values(ROLES);
const allPermissions = Object.values(PERMISSIONS);

// Mock: store permission changes in local state
const getInitialMatrix = () => {
  const matrix = {};
  allRoles.forEach((role) => {
    matrix[role] = new Set(ROLE_PERMISSIONS[role] || []);
  });
  return matrix;
};

const PermissionMatrix = () => {
  const [matrix, setMatrix] = useState(getInitialMatrix());
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  const handleToggle = (role, permission) => {
    setMatrix((prev) => {
      const updated = { ...prev };
      const perms = new Set(updated[role]);
      if (perms.has(permission)) {
        perms.delete(permission);
      } else {
        perms.add(permission);
      }
      updated[role] = perms;
      return updated;
    });
  };

  const handleSave = async () => {
    setMessage("");
    setError("");
    try {
      // Mock: log changes to audit log
      await authService.addAuditLog(
        1, // admin user id (mock)
        "permission_update",
        {
          matrix: Object.fromEntries(
            Object.entries(matrix).map(([role, perms]) => [
              role,
              Array.from(perms),
            ]),
          ),
        },
      );
      setMessage("Permissions updated and logged (mock).");
    } catch (e) {
      setError("Failed to log permission change.");
    }
  };

  return (
    <Card className="my-4">
      <Card.Body>
        <Card.Title>Permission Matrix</Card.Title>
        {message && <Alert variant="success">{message}</Alert>}
        {error && <Alert variant="danger">{error}</Alert>}
        <Table bordered responsive>
          <thead>
            <tr>
              <th>Permission</th>
              {allRoles.map((role) => (
                <th key={role}>{role.replace("_", " ").toUpperCase()}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {allPermissions.map((permission) => (
              <tr key={permission}>
                <td>{permission.replace("_", " ")}</td>
                {allRoles.map((role) => (
                  <td key={role} className="text-center">
                    <input
                      type="checkbox"
                      checked={matrix[role].has(permission)}
                      onChange={() => handleToggle(role, permission)}
                    />
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </Table>
        <Button onClick={handleSave} variant="primary">
          Save Changes
        </Button>
      </Card.Body>
    </Card>
  );
};

export default PermissionMatrix;
