import React from "react";
import { Card, Button, Row, Col } from "react-bootstrap";
import { useTheme } from "../../components/common";

const themePreviews = {
  "theme-teal": {
    bg: "linear-gradient(135deg, #007072 60%, #8DC63F 100%)",
    text: "#333333",
  },
  "theme-blue": {
    bg: "linear-gradient(135deg, #002B45 60%, #00D4FF 100%)",
    text: "#F2F2F2",
  },
  "theme-earth": {
    bg: "linear-gradient(135deg, #556B2F 60%, #E07B00 100%)",
    text: "#3B2F2F",
  },
};

const ThemeSettings = () => {
  const { theme, setTheme, themes } = useTheme();

  return (
    <div className="container py-4">
      <h2 className="mb-4">Theme Settings</h2>
      <Row>
        {themes.map((t) => (
          <Col md={4} key={t.key} className="mb-4">
            <Card
              className={`shadow-sm h-100 ${theme === t.key ? "border-primary" : ""}`}
              style={{
                borderWidth: 2,
                background: themePreviews[t.key].bg,
                color: themePreviews[t.key].text,
                transition: "box-shadow 0.2s, border 0.2s",
              }}
            >
              <Card.Body>
                <Card.Title className="fw-bold">{t.name}</Card.Title>
                <Card.Text>{t.description}</Card.Text>
                <Button
                  variant={theme === t.key ? "primary" : "outline-primary"}
                  onClick={() => setTheme(t.key)}
                  disabled={theme === t.key}
                >
                  {theme === t.key ? "Selected" : "Apply Theme"}
                </Button>
              </Card.Body>
            </Card>
          </Col>
        ))}
      </Row>
    </div>
  );
};

export default ThemeSettings;
