import React, { useState, useEffect } from "react";
import {
  Card,
  Row,
  Col,
  Badge,
  Form,
  Button,
  Modal,
} from "react-bootstrap";
import ButtonGroup from "react-bootstrap/ButtonGroup";
import Table from "react-bootstrap/Table";
import DriveEtaIcon from "@mui/icons-material/DriveEta";
import ViewModuleIcon from "@mui/icons-material/ViewModule";
import ViewListIcon from "@mui/icons-material/ViewList";

const dummyDrivers = [
  {
    id: 1,
    name: "John Doe",
    email: "john@drivers.com",
    phone: "123-456-7890",
    documents: "License.pdf",
    paymentDetails: "Bank: ABC, Acc: 123456",
    assignedVehicles: [1],
  },
  {
    id: 2,
    name: "Jane Smith",
    email: "jane@drivers.com",
    phone: "987-654-3210",
    documents: "License.pdf",
    paymentDetails: "Bank: XYZ, Acc: 654321",
    assignedVehicles: [],
  },
];

const dummyVehicles = [
  { id: 1, name: "Truck 101" },
  { id: 2, name: "Van 202" },
  { id: 3, name: "Car 303" },
];

const DRIVERS_KEY = "driversData";

const loadDrivers = () => {
  const data = localStorage.getItem(DRIVERS_KEY);
  return data ? JSON.parse(data) : dummyDrivers;
};
const saveDrivers = (drivers) => {
  localStorage.setItem(DRIVERS_KEY, JSON.stringify(drivers));
};

const DriverManagementPage = () => {
  const [drivers, setDrivers] = useState(loadDrivers());
  const [search, setSearch] = useState("");
  const [view, setView] = useState("grid");
  const [showAddEditModal, setShowAddEditModal] = useState(false);
  const [editDriverIndex, setEditDriverIndex] = useState(null);
  const [newDriver, setNewDriver] = useState({
    name: "",
    email: "",
    phone: "",
    documents: "",
    paymentDetails: "",
    assignedVehicles: [],
  });
  const [showAssignVehicleModal, setShowAssignVehicleModal] = useState(false);
  const [selectedDriver, setSelectedDriver] = useState(null);
  const [vehicleSelection, setVehicleSelection] = useState([]);

  useEffect(() => {
    saveDrivers(drivers);
  }, [drivers]);

  const filteredDrivers = drivers.filter((driver) =>
    driver.name.toLowerCase().includes(search.toLowerCase()) ||
    driver.email.toLowerCase().includes(search.toLowerCase())
  );

  const handleAddDriver = () => {
    setShowAddEditModal(true);
    setEditDriverIndex(null);
    setNewDriver({
      name: "",
      email: "",
      phone: "",
      documents: "",
      paymentDetails: "",
      assignedVehicles: [],
    });
  };

  const handleEditDriver = (driver, idx) => {
    setEditDriverIndex(idx);
    setNewDriver({ ...driver });
    setShowAddEditModal(true);
  };

  const handleSaveDriver = () => {
    if (!newDriver.name || !newDriver.email) return;
    let updatedDrivers;
    if (editDriverIndex !== null) {
      updatedDrivers = drivers.map((d, i) =>
        i === editDriverIndex ? { ...d, ...newDriver } : d
      );
    } else {
      updatedDrivers = [
        ...drivers,
        { ...newDriver, id: Date.now(), assignedVehicles: [] },
      ];
    }
    setDrivers(updatedDrivers);
    setShowAddEditModal(false);
    setEditDriverIndex(null);
  };

  const handleDeleteDriver = (idx) => {
    setDrivers(drivers.filter((_, i) => i !== idx));
  };

  const handleAssignVehicle = (driver) => {
    setSelectedDriver(driver);
    setVehicleSelection(driver.assignedVehicles || []);
    setShowAssignVehicleModal(true);
  };

  const handleSaveVehicleAssignment = () => {
    if (!selectedDriver) return;
    const updatedDrivers = drivers.map((d) =>
      d.id === selectedDriver.id ? { ...d, assignedVehicles: vehicleSelection } : d
    );
    setDrivers(updatedDrivers);
    setShowAssignVehicleModal(false);
    setSelectedDriver(null);
  };

  const handleVehicleCheckbox = (vehicleId) => {
    setVehicleSelection((prev) =>
      prev.includes(vehicleId)
        ? prev.filter((id) => id !== vehicleId)
        : [...prev, vehicleId]
    );
  };

  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h2>Driver Management</h2>
        <ButtonGroup>
          <Button
            variant={view === "grid" ? "primary" : "outline-primary"}
            onClick={() => setView("grid")}
            title="Grid View"
          >
            <ViewModuleIcon />
          </Button>
          <Button
            variant={view === "list" ? "primary" : "outline-primary"}
            onClick={() => setView("list")}
            title="List View"
          >
            <ViewListIcon />
          </Button>
        </ButtonGroup>
      </div>
      <Form.Group className="mb-3">
        <Form.Control
          type="text"
          placeholder="Search drivers by name or email..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </Form.Group>
      <Button variant="success" className="mb-3" onClick={handleAddDriver}>
        Add Driver
      </Button>
      {view === "grid" ? (
        <Row>
          {filteredDrivers.map((driver, idx) => (
            <Col key={driver.id} lg={6} className="mb-4">
              <Card>
                <Card.Header className="d-flex justify-content-between align-items-center">
                  <div>
                    <h5 className="mb-0">{driver.name}</h5>
                    <Badge bg="info">Driver</Badge>
                  </div>
                </Card.Header>
                <Card.Body>
                  <div><strong>Email:</strong> {driver.email}</div>
                  <div><strong>Phone:</strong> {driver.phone}</div>
                  <div><strong>Documents:</strong> {driver.documents}</div>
                  <div><strong>Payment Details:</strong> {driver.paymentDetails}</div>
                  <div><strong>Assigned Vehicles:</strong> {driver.assignedVehicles?.map(id => dummyVehicles.find(v => v.id === id)?.name).filter(Boolean).join(", ") || "None"}</div>
                  <div className="mt-3 d-flex gap-2">
                    <Button size="sm" onClick={() => handleAssignVehicle(driver)} variant="outline-primary">Assign Vehicles</Button>
                    <Button size="sm" onClick={() => handleEditDriver(driver, idx)} variant="outline-secondary">Edit</Button>
                    <Button size="sm" onClick={() => handleDeleteDriver(idx)} variant="outline-danger">Delete</Button>
                  </div>
                </Card.Body>
              </Card>
            </Col>
          ))}
        </Row>
      ) : (
        <Card>
          <Card.Body>
            <Table responsive striped hover>
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Email</th>
                  <th>Phone</th>
                  <th>Documents</th>
                  <th>Payment Details</th>
                  <th>Assigned Vehicles</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredDrivers.map((driver, idx) => (
                  <tr key={driver.id}>
                    <td>{driver.name}</td>
                    <td>{driver.email}</td>
                    <td>{driver.phone}</td>
                    <td>{driver.documents}</td>
                    <td>{driver.paymentDetails}</td>
                    <td>{driver.assignedVehicles?.map(id => dummyVehicles.find(v => v.id === id)?.name).filter(Boolean).join(", ") || "None"}</td>
                    <td>
                      <Button size="sm" onClick={() => handleAssignVehicle(driver)} variant="outline-primary" className="me-1">Assign Vehicles</Button>
                      <Button size="sm" onClick={() => handleEditDriver(driver, idx)} variant="outline-secondary" className="me-1">Edit</Button>
                      <Button size="sm" onClick={() => handleDeleteDriver(idx)} variant="outline-danger">Delete</Button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </Table>
          </Card.Body>
        </Card>
      )}

      {/* Add/Edit Driver Modal */}
      <Modal show={showAddEditModal} onHide={() => { setShowAddEditModal(false); setEditDriverIndex(null); }}>
        <Modal.Header closeButton>
          <Modal.Title>{editDriverIndex !== null ? 'Edit' : 'Add'} Driver</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form>
            <Form.Group className="mb-3">
              <Form.Label>Name</Form.Label>
              <Form.Control
                type="text"
                value={newDriver.name}
                onChange={(e) => setNewDriver({ ...newDriver, name: e.target.value })}
                placeholder="Driver Name"
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Email</Form.Label>
              <Form.Control
                type="email"
                value={newDriver.email}
                onChange={(e) => setNewDriver({ ...newDriver, email: e.target.value })}
                placeholder="Driver Email"
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Phone Number</Form.Label>
              <Form.Control
                type="text"
                value={newDriver.phone}
                onChange={(e) => setNewDriver({ ...newDriver, phone: e.target.value })}
                placeholder="Phone Number"
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Documents</Form.Label>
              <Form.Control
                type="text"
                value={newDriver.documents}
                onChange={(e) => setNewDriver({ ...newDriver, documents: e.target.value })}
                placeholder="Documents (e.g. License.pdf)"
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Payment Details</Form.Label>
              <Form.Control
                type="text"
                value={newDriver.paymentDetails}
                onChange={(e) => setNewDriver({ ...newDriver, paymentDetails: e.target.value })}
                placeholder="Payment Details"
              />
            </Form.Group>
          </Form>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => { setShowAddEditModal(false); setEditDriverIndex(null); }}>Cancel</Button>
          <Button variant="primary" onClick={handleSaveDriver}>Save</Button>
        </Modal.Footer>
      </Modal>

      {/* Assign Vehicle Modal */}
      <Modal show={showAssignVehicleModal} onHide={() => setShowAssignVehicleModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>Assign Vehicles to {selectedDriver?.name}</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form>
            {dummyVehicles.map((vehicle) => (
              <Form.Check
                key={vehicle.id}
                type="checkbox"
                label={vehicle.name}
                checked={vehicleSelection.includes(vehicle.id)}
                onChange={() => handleVehicleCheckbox(vehicle.id)}
              />
            ))}
          </Form>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowAssignVehicleModal(false)}>Cancel</Button>
          <Button variant="primary" onClick={handleSaveVehicleAssignment}>Save</Button>
        </Modal.Footer>
      </Modal>
    </div>
  );
};

export default DriverManagementPage; 