import React from "react";
import { Card, Form } from "react-bootstrap";

const defaultPresets = [
  { label: "Default Delivery", value: "delivery" },
  { label: "Express Route", value: "express" },
  { label: "Night Trip", value: "night" },
];

const QuickTripSettings = ({ instant = false, onChange, presetOptions }) => {
  const presets = presetOptions || defaultPresets;

  const handleInstantChange = (e) => {
    onChange && onChange({ instant: e.target.checked });
  };

  const handlePresetChange = (e) => {
    onChange && onChange({ instant: true, preset: e.target.value });
  };

  return (
    <Card className="mb-3">
      <Card.Header>
        <h5 className="mb-0">Instant Trip Settings</h5>
      </Card.Header>
      <Card.Body>
        <Form.Check
          type="switch"
          id="instant-trip-switch"
          label="Enable Instant Trip"
          checked={instant}
          onChange={handleInstantChange}
          className="mb-3"
        />
        {instant && (
          <Form.Group>
            <Form.Label>Quick Preset</Form.Label>
            <Form.Select onChange={handlePresetChange} defaultValue="">
              <option value="">Select a preset...</option>
              {presets.map((p) => (
                <option key={p.value} value={p.value}>{p.label}</option>
              ))}
            </Form.Select>
          </Form.Group>
        )}
      </Card.Body>
    </Card>
  );
};

export default QuickTripSettings; 