import React from "react";
import { Card, Button } from "react-bootstrap";
import { useNavigate } from "react-router-dom";

const ClientDetailsPage = () => {
  const navigate = useNavigate();
  // Dummy data for now
  const client = {
    id: 1,
    name: "Acme Corp",
    createdAt: "2023-01-10",
    enabled: true,
    activePlan: "Premium",
    contactPerson: "Alice Smith",
    billingDetails: "alice@acme.com, 123-456-7890, 123 Main St",
  };
  return (
    <Card>
      <Card.Header>
        <h3>Client Details</h3>
      </Card.Header>
      <Card.Body>
        <div><strong>Name:</strong> {client.name}</div>
        <div><strong>Contact Person:</strong> {client.contactPerson}</div>
        <div><strong>Active Plan:</strong> {client.activePlan}</div>
        <div><strong>Billing Details:</strong> {client.billingDetails}</div>
        <div><strong>Enabled:</strong> {client.enabled ? "Yes" : "No"}</div>
        <div><strong>Created At:</strong> {client.createdAt}</div>
        <Button className="mt-3" onClick={() => navigate(-1)}>
          Back
        </Button>
      </Card.Body>
    </Card>
  );
};

export default ClientDetailsPage; 