import React from "react";
import { useSelector } from "react-redux";
import { Card, Badge, ListGroup } from "react-bootstrap";

const ClientDashboardPage = () => {
  const currentClient = useSelector((state) => state.auth.currentClient);
  const clientPermissions = useSelector((state) => state.auth.clientPermissions);

  if (!currentClient) {
    return <div className="text-center mt-5">No client selected. Please use Switch Client.</div>;
  }

  return (
    <div className="d-flex justify-content-center align-items-center min-vh-100">
      <Card style={{ minWidth: 400 }} className="shadow-lg">
        <Card.Header>
          <h4 className="mb-0">Welcome to {currentClient.name} Dashboard</h4>
          <Badge bg={currentClient.enabled ? "success" : "secondary"} className="ms-2">
            {currentClient.enabled ? "Enabled" : "Disabled"}
          </Badge>
        </Card.Header>
        <Card.Body>
          <div><strong>Contact:</strong> {currentClient.contactPerson}</div>
          <div><strong>Active Plan:</strong> {currentClient.activePlan}</div>
          <div><strong>Billing:</strong> {currentClient.billingDetails}</div>
          <div><strong>Created At:</strong> {currentClient.createdAt}</div>
          <hr />
          <h6>Permissions:</h6>
          <ListGroup>
            {clientPermissions.length === 0 ? (
              <ListGroup.Item>No permissions assigned.</ListGroup.Item>
            ) : (
              clientPermissions.map((perm) => (
                <ListGroup.Item key={perm}>{perm}</ListGroup.Item>
              ))
            )}
          </ListGroup>
        </Card.Body>
      </Card>
    </div>
  );
};

export default ClientDashboardPage; 