import React, { useState } from "react";
import { useForm } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import * as yup from "yup";
import { Button, Form, Card, Spinner, Alert } from "react-bootstrap";
import { authService } from "../../services";
import { ROLES } from "../../routes/permissions";

const schema = yup.object().shape({
  email: yup.string().email("Invalid email").required("Email is required"),
  password: yup
    .string()
    .min(6, "Password must be at least 6 characters")
    .required("Password is required"),
  role: yup
    .string()
    .oneOf(Object.values(ROLES), "Select a valid role")
    .required("Role is required"),
});

const roleLabels = {
  [ROLES.ADMIN]: "Admin",
  [ROLES.FLEET_MANAGER]: "Fleet Manager",
  [ROLES.DRIVER]: "Driver",
  [ROLES.GPS_TECHNICIAN]: "GPS Technician",
  [ROLES.CUSTOMER]: "Customer",
};

const Register = () => {
  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm({
    resolver: yupResolver(schema),
  });
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [registered, setRegistered] = useState(false);
  const [pendingApproval, setPendingApproval] = useState(false);

  const onSubmit = async (data) => {
    setLoading(true);
    setError("");
    setMessage("");
    setRegistered(false);
    setPendingApproval(false);
    try {
      const res = await authService.register(data);
      setMessage(res.data.message);
      setRegistered(true);
      if ([ROLES.FLEET_MANAGER, ROLES.GPS_TECHNICIAN].includes(data.role)) {
        setPendingApproval(true);
      }
    } catch (e) {
      setError(e.response?.data?.message || "Registration failed");
    }
    setLoading(false);
  };

  return (
    <div className="d-flex justify-content-center align-items-center min-vh-100 bg-light">
      <Card style={{ width: 400 }}>
        <Card.Body>
          <h3 className="mb-4 text-center">Register</h3>
          {message && <Alert variant="info">{message}</Alert>}
          {error && <Alert variant="danger">{error}</Alert>}
          {registered ? (
            <>
              <p>Please check your email to verify your account.</p>
              {pendingApproval && (
                <Alert variant="warning">
                  Your registration requires admin approval. You will be
                  notified once approved.
                </Alert>
              )}
            </>
          ) : (
            <Form onSubmit={handleSubmit(onSubmit)}>
              <Form.Group className="mb-3">
                <Form.Label>Name</Form.Label>
                <Form.Control
                  type="text"
                  {...register("name")}
                  isInvalid={!!errors.name}
                />
                <Form.Control.Feedback type="invalid">
                  {errors.name?.message}
                </Form.Control.Feedback>
              </Form.Group>
              <Form.Group className="mb-3">
                <Form.Label>Email</Form.Label>
                <Form.Control
                  type="email"
                  {...register("email")}
                  isInvalid={!!errors.email}
                />
                <Form.Control.Feedback type="invalid">
                  {errors.email?.message}
                </Form.Control.Feedback>
              </Form.Group>
              <Form.Group className="mb-3">
                <Form.Label>Password</Form.Label>
                <Form.Control
                  type="password"
                  {...register("password")}
                  isInvalid={!!errors.password}
                />
                <Form.Control.Feedback type="invalid">
                  {errors.password?.message}
                </Form.Control.Feedback>
              </Form.Group>
              <Form.Group className="mb-3">
                <Form.Label>Role</Form.Label>
                <Form.Select
                  {...register("role")}
                  isInvalid={!!errors.role}
                  defaultValue=""
                >
                  <option value="" disabled>
                    Select role
                  </option>
                  {Object.values(ROLES).map((role) => (
                    <option key={role} value={role}>
                      {roleLabels[role]}
                    </option>
                  ))}
                </Form.Select>
                <Form.Control.Feedback type="invalid">
                  {errors.role?.message}
                </Form.Control.Feedback>
              </Form.Group>
              <Button
                type="submit"
                variant="primary"
                className="w-100"
                disabled={loading}
              >
                {loading ? (
                  <Spinner animation="border" size="sm" />
                ) : (
                  "Register"
                )}
              </Button>
            </Form>
          )}
        </Card.Body>
      </Card>
    </div>
  );
};

export default Register;
