import React, { useState } from "react";
import {
  Table,
  Button,
  Form,
  Card,
  Row,
  Col,
  Badge,
  Modal,
  ButtonGroup,
  Pagination,
} from "react-bootstrap";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import AddIcon from "@mui/icons-material/Add";
import VisibilityIcon from "@mui/icons-material/Visibility";
import ViewModuleIcon from "@mui/icons-material/ViewModule";
import ViewListIcon from "@mui/icons-material/ViewList";

// Dummy data for roles
const dummyRoles = [
  {
    id: 1,
    name: "ADMIN",
    description: "Full system access with all permissions",
    permissions: [
      "user_management",
      "team_management",
      "fleet_oversight",
      "admin_access",
    ],
    userCount: 2,
    isDefault: false,
    createdAt: "2023-01-01",
  },
  {
    id: 2,
    name: "USER",
    description: "Standard user with basic fleet access",
    permissions: ["fleet_oversight"],
    userCount: 8,
    isDefault: true,
    createdAt: "2023-01-01",
  },
  {
    id: 3,
    name: "MANAGER",
    description: "Team manager with user and team management",
    permissions: ["user_management", "team_management", "fleet_oversight"],
    userCount: 3,
    isDefault: false,
    createdAt: "2023-03-15",
  },
  {
    id: 4,
    name: "OPERATOR",
    description: "Fleet operator with vehicle management",
    permissions: ["fleet_oversight"],
    userCount: 5,
    isDefault: false,
    createdAt: "2023-06-20",
  },
];

// Available permissions
const availablePermissions = [
  {
    key: "user_management",
    label: "User Management",
    description: "Manage users and their accounts",
  },
  {
    key: "team_management",
    label: "Team Management",
    description: "Create and manage teams",
  },
  {
    key: "fleet_oversight",
    label: "Fleet Oversight",
    description: "Access to vehicle management",
  },
  {
    key: "admin_access",
    label: "Admin Access",
    description: "Full administrative access",
  },
  {
    key: "audit_logs",
    label: "Audit Logs",
    description: "View system audit logs",
  },
  {
    key: "permissions_manage",
    label: "Manage Permissions",
    description: "Manage role permissions",
  },
];

const UserRoles = () => {
  const [roles, setRoles] = useState(dummyRoles);
  const [showModal, setShowModal] = useState(false);
  const [editingRole, setEditingRole] = useState(null);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [selectedRole, setSelectedRole] = useState(null);
  const [view, setView] = useState("grid"); // 'grid' or 'list'
  const PAGE_SIZE = 6;
  const [page, setPage] = useState(1);
  const totalPages = Math.ceil(roles.length / PAGE_SIZE);
  const pagedRoles = roles.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  const handleSaveRole = (roleData) => {
    if (editingRole) {
      setRoles(
        roles.map((role) =>
          role.id === editingRole.id ? { ...role, ...roleData } : role,
        ),
      );
    } else {
      const newRole = {
        id: Math.max(...roles.map((r) => r.id)) + 1,
        ...roleData,
        userCount: 0,
        createdAt: new Date().toISOString().split("T")[0],
      };
      setRoles([...roles, newRole]);
    }
    setShowModal(false);
    setEditingRole(null);
  };

  const handleDeleteRole = () => {
    setRoles(roles.filter((role) => role.id !== selectedRole.id));
    setShowDeleteModal(false);
    setSelectedRole(null);
  };

  const getPermissionBadge = (permission) => {
    const perm = availablePermissions.find((p) => p.key === permission);
    return (
      <Badge key={permission} bg="info" className="me-1 mb-1">
        {perm?.label || permission}
      </Badge>
    );
  };

  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h2>User Roles Management</h2>
        <div className="d-flex align-items-center gap-2">
          <ButtonGroup>
            <Button
              variant={view === "grid" ? "primary" : "outline-primary"}
              onClick={() => setView("grid")}
              title="Grid View"
            >
              <ViewModuleIcon />
            </Button>
            <Button
              variant={view === "list" ? "primary" : "outline-primary"}
              onClick={() => setView("list")}
              title="List View"
            >
              <ViewListIcon />
            </Button>
          </ButtonGroup>
          <Button variant="primary" onClick={() => setShowModal(true)}>
            <AddIcon className="me-2" />
            Add Role
          </Button>
        </div>
      </div>

      {/* Roles Grid or List */}
      {view === "grid" ? (
        <Row>
          {pagedRoles.map((role) => (
            <Col key={role.id} lg={6} className="mb-4">
              <Card>
                <Card.Header className="d-flex justify-content-between align-items-center">
                  <div>
                    <h5 className="mb-0">{role.name}</h5>
                    {role.isDefault && (
                      <Badge bg="success" className="ms-2">
                        Default
                      </Badge>
                    )}
                  </div>
                  <div className="d-flex gap-1">
                    <Button
                      size="sm"
                      variant="outline-primary"
                      title="View Details"
                    >
                      <VisibilityIcon />
                    </Button>
                    <Button
                      size="sm"
                      variant="outline-warning"
                      title="Edit Role"
                      onClick={() => {
                        setEditingRole(role);
                        setShowModal(true);
                      }}
                    >
                      <EditIcon />
                    </Button>
                    {!role.isDefault && (
                      <Button
                        size="sm"
                        variant="outline-danger"
                        title="Delete Role"
                        onClick={() => {
                          setSelectedRole(role);
                          setShowDeleteModal(true);
                        }}
                      >
                        <DeleteIcon />
                      </Button>
                    )}
                  </div>
                </Card.Header>
                <Card.Body>
                  <p className="text-muted mb-3">{role.description}</p>
                  <div className="mb-3">
                    <strong>Permissions:</strong>
                    <div className="mt-2">
                      {role.permissions.map((permission) =>
                        getPermissionBadge(permission),
                      )}
                    </div>
                  </div>
                  <div className="d-flex justify-content-between text-muted">
                    <small>{role.userCount} users</small>
                    <small>Created: {role.createdAt}</small>
                  </div>
                </Card.Body>
              </Card>
            </Col>
          ))}
          {/* Pagination for grid view */}
          {totalPages > 1 && (
            <div className="d-flex justify-content-center mt-3">
              <Pagination>
                <Pagination.First
                  onClick={() => setPage(1)}
                  disabled={page === 1}
                />
                <Pagination.Prev
                  onClick={() => setPage((p) => Math.max(1, p - 1))}
                  disabled={page === 1}
                />
                {[...Array(totalPages)].map((_, idx) => (
                  <Pagination.Item
                    key={idx + 1}
                    active={page === idx + 1}
                    onClick={() => setPage(idx + 1)}
                  >
                    {idx + 1}
                  </Pagination.Item>
                ))}
                <Pagination.Next
                  onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                  disabled={page === totalPages}
                />
                <Pagination.Last
                  onClick={() => setPage(totalPages)}
                  disabled={page === totalPages}
                />
              </Pagination>
            </div>
          )}
        </Row>
      ) : (
        <Card>
          <Card.Body>
            <Table responsive striped hover>
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Description</th>
                  <th>Permissions</th>
                  <th>Users</th>
                  <th>Default</th>
                  <th>Created</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {pagedRoles.map((role) => (
                  <tr key={role.id}>
                    <td>{role.name}</td>
                    <td>{role.description}</td>
                    <td>
                      {role.permissions.map((permission) =>
                        getPermissionBadge(permission),
                      )}
                    </td>
                    <td>{role.userCount}</td>
                    <td>
                      {role.isDefault ? (
                        <Badge bg="success">Default</Badge>
                      ) : (
                        ""
                      )}
                    </td>
                    <td>{role.createdAt}</td>
                    <td>
                      <div className="d-flex gap-1">
                        <Button
                          size="sm"
                          variant="outline-primary"
                          title="View Details"
                        >
                          <VisibilityIcon />
                        </Button>
                        <Button
                          size="sm"
                          variant="outline-warning"
                          title="Edit Role"
                          onClick={() => {
                            setEditingRole(role);
                            setShowModal(true);
                          }}
                        >
                          <EditIcon />
                        </Button>
                        {!role.isDefault && (
                          <Button
                            size="sm"
                            variant="outline-danger"
                            title="Delete Role"
                            onClick={() => {
                              setSelectedRole(role);
                              setShowDeleteModal(true);
                            }}
                          >
                            <DeleteIcon />
                          </Button>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </Table>
            {/* Pagination for table view */}
            {totalPages > 1 && (
              <div className="d-flex justify-content-center mt-3">
                <Pagination>
                  <Pagination.First
                    onClick={() => setPage(1)}
                    disabled={page === 1}
                  />
                  <Pagination.Prev
                    onClick={() => setPage((p) => Math.max(1, p - 1))}
                    disabled={page === 1}
                  />
                  {[...Array(totalPages)].map((_, idx) => (
                    <Pagination.Item
                      key={idx + 1}
                      active={page === idx + 1}
                      onClick={() => setPage(idx + 1)}
                    >
                      {idx + 1}
                    </Pagination.Item>
                  ))}
                  <Pagination.Next
                    onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                    disabled={page === totalPages}
                  />
                  <Pagination.Last
                    onClick={() => setPage(totalPages)}
                    disabled={page === totalPages}
                  />
                </Pagination>
              </div>
            )}
          </Card.Body>
        </Card>
      )}

      {/* Add/Edit Role Modal */}
      <Modal
        show={showModal}
        onHide={() => {
          setShowModal(false);
          setEditingRole(null);
        }}
        size="lg"
        centered
        backdrop="static"
        style={{ zIndex: 2000 }}
      >
        <Modal.Header closeButton>
          <Modal.Title>
            {editingRole ? "Edit Role" : "Add New Role"}
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form>
            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Role Name</Form.Label>
                  <Form.Control
                    type="text"
                    placeholder="Enter role name"
                    defaultValue={editingRole?.name}
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Default Role</Form.Label>
                  <Form.Check
                    type="checkbox"
                    label="Set as default role for new users"
                    defaultChecked={editingRole?.isDefault}
                  />
                </Form.Group>
              </Col>
            </Row>
            <Form.Group className="mb-3">
              <Form.Label>Description</Form.Label>
              <Form.Control
                as="textarea"
                rows={3}
                placeholder="Enter role description"
                defaultValue={editingRole?.description}
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Permissions</Form.Label>
              <div className="border rounded p-3">
                {availablePermissions.map((permission) => (
                  <Form.Check
                    key={permission.key}
                    type="checkbox"
                    id={`perm-${permission.key}`}
                    label={
                      <div>
                        <strong>{permission.label}</strong>
                        <br />
                        <small className="text-muted">
                          {permission.description}
                        </small>
                      </div>
                    }
                    defaultChecked={editingRole?.permissions?.includes(
                      permission.key,
                    )}
                    className="mb-2"
                  />
                ))}
              </div>
            </Form.Group>
          </Form>
        </Modal.Body>
        <Modal.Footer>
          <Button
            variant="secondary"
            onClick={() => {
              setShowModal(false);
              setEditingRole(null);
            }}
          >
            Cancel
          </Button>
          <Button variant="primary">
            {editingRole ? "Update Role" : "Create Role"}
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Delete Confirmation Modal */}
      <Modal
        show={showDeleteModal}
        onHide={() => setShowDeleteModal(false)}
        centered
        backdrop="static"
        style={{ zIndex: 2000 }}
      >
        <Modal.Header closeButton>
          <Modal.Title>Confirm Delete</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          Are you sure you want to delete the role{" "}
          <strong>{selectedRole?.name}</strong>? This will affect{" "}
          {selectedRole?.userCount} users currently assigned to this role.
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowDeleteModal(false)}>
            Cancel
          </Button>
          <Button variant="danger" onClick={handleDeleteRole}>
            Delete Role
          </Button>
        </Modal.Footer>
      </Modal>
    </div>
  );
};

export default UserRoles;
