import React, { useEffect, useState } from "react";
import { Table, Card, Spinner } from "react-bootstrap";
import { getAuditLogs } from "../../services/user.service";
import { getVehicleAuditLogs } from "../../services/vehicle.service";

const AuditLog = ({ vehicleId }) => {
  const [logs, setLogs] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    setLoading(true);
    const fetchLogs = vehicleId ? getVehicleAuditLogs(vehicleId) : getAuditLogs();
    fetchLogs.then((res) => {
      setLogs(res.data);
      setLoading(false);
    });
  }, [vehicleId]);

  return (
    <Card className="my-4">
      <Card.Body>
        <Card.Title>{vehicleId ? "Vehicle Audit Logs" : "Audit Logs"}</Card.Title>
        {loading ? (
          <Spinner animation="border" />
        ) : (
          <Table striped bordered hover>
            <thead>
              <tr>
                <th>ID</th>
                {vehicleId && <th>Vehicle ID</th>}
                <th>User ID</th>
                <th>Action</th>
                <th>Details</th>
                <th>Timestamp</th>
              </tr>
            </thead>
            <tbody>
              {logs.map((log) => (
                <tr key={log.id}>
                  <td>{log.id}</td>
                  {vehicleId && <td>{log.vehicleId}</td>}
                  <td>{log.userId}</td>
                  <td>{log.action}</td>
                  <td>{JSON.stringify(log.details)}</td>
                  <td>{new Date(log.timestamp).toLocaleString()}</td>
                </tr>
              ))}
            </tbody>
          </Table>
        )}
      </Card.Body>
    </Card>
  );
};

export default AuditLog;
