import React from "react";
import { Navbar, Nav, Dropdown } from "react-bootstrap";
import { useSelector, useDispatch } from "react-redux";
import { logout } from "../../slices/authSlice";
import { Outlet, useNavigate } from "react-router-dom";
import AccountCircleIcon from "@mui/icons-material/AccountCircle";
import SettingsIcon from "@mui/icons-material/Settings";
import Sidebar from "./Sidebar";

const MainLayout = () => {
  const { user } = useSelector((state) => state.auth);
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const handleLogout = () => {
    dispatch(logout());
  };

  return (
    <div
      className="main-layout"
      style={{
        minHeight: "100vh",
        background: "var(--neutral-light)",
        display: "flex",
        flexDirection: "column",
      }}
    >
      <Navbar
        style={{
          minHeight: 64,
          marginLeft: 0,
          zIndex: 1200,
          background: "var(--primary)",
          color: "var(--neutral-light)",
          boxShadow: "0 2px 16px rgba(0,0,0,0.10)",
          backdropFilter: "blur(8px)",
          borderBottom: "1.5px solid rgba(255,255,255,0.12)",
        }}
        variant="dark"
        expand="lg"
        className="shadow-sm px-3"
      >
        <Navbar.Brand
          style={{
            fontWeight: 700,
            fontSize: 22,
            color: "var(--neutral-light)",
            letterSpacing: 1,
          }}
        >
          GPS Dashboard
        </Navbar.Brand>
        <Nav className="ms-auto align-items-center">
          <span
            className="me-2 fw-bold"
            style={{ color: "var(--neutral-light)" }}
          >
            Welcome, {user?.name}
          </span>
          <Dropdown align="end">
            <Dropdown.Toggle
              variant="light"
              id="dropdown-user"
              className="d-flex align-items-center border-0 shadow-none"
              style={{ background: "none" }}
            >
              <AccountCircleIcon
                style={{ fontSize: 36, color: "var(--neutral-light)" }}
              />
            </Dropdown.Toggle>
            <Dropdown.Menu className="shadow rounded-4">
              <Dropdown.Item onClick={() => navigate("/profile")}>
                Profile
              </Dropdown.Item>
              <Dropdown.Item onClick={() => navigate("/switch-client")}>
                Switch Client
              </Dropdown.Item>
              <Dropdown.Item onClick={() => navigate("/theme-settings")}>
                Theme Settings <SettingsIcon className="ms-2" />
              </Dropdown.Item>
              <Dropdown.Divider />
              <Dropdown.Item
                onClick={handleLogout}
                className="text-danger fw-bold"
              >
                Logout
              </Dropdown.Item>
            </Dropdown.Menu>
          </Dropdown>
        </Nav>
      </Navbar>
      <div style={{ display: "flex", flex: 1, minHeight: 0 }}>
        <Sidebar role={user?.role} permissions={user?.permissions} />
        <main style={{ flex: 1, minHeight: 0, padding: 32, overflow: "auto" }}>
          <Outlet />
        </main>
      </div>
    </div>
  );
};

export default MainLayout;
