import React from "react";
import { Row, Col } from "react-bootstrap";

const CardGrid = ({
  items,
  renderCard,
  cols = { xs: 12, sm: 6, md: 4, lg: 3 },
}) => (
  <Row>
    {items.map((item, idx) => (
      <Col key={item.id || idx} {...cols} className="mb-4">
        {renderCard(item)}
      </Col>
    ))}
  </Row>
);

export default CardGrid;
