import { useEffect } from 'react';
import { useDispatch } from 'react-redux';
import { trackingWebSocket } from '../services/tracking.service';
import { updateRealTimeLocation, setConnectionStatus } from '../slices/trackingSlice';

export const useRealTimeTracking = (vehicleIds) => {
  const dispatch = useDispatch();

  useEffect(() => {
    if (!vehicleIds || vehicleIds.length === 0) return;
    trackingWebSocket.connect(vehicleIds);
    dispatch(setConnectionStatus('connected'));

    const handleLocationUpdate = (data) => {
      dispatch(updateRealTimeLocation({ vehicleId: data.vehicleId, location: data.location }));
    };

    trackingWebSocket.subscribe('location_update', handleLocationUpdate);

    return () => {
      trackingWebSocket.unsubscribe('location_update', handleLocationUpdate);
      trackingWebSocket.disconnect();
      dispatch(setConnectionStatus('disconnected'));
    };
    // eslint-disable-next-line
  }, [JSON.stringify(vehicleIds)]);
}; 