import React from "react";
import { Card, Form, OverlayTrigger, Tooltip } from "react-bootstrap";
import { InfoCircle } from "react-bootstrap-icons";

const RecurringTripScheduler = ({ schedule = { type: "one-time", cron: "" }, onChange }) => {
  const handleTypeChange = (e) => {
    onChange && onChange({ ...schedule, type: e.target.value });
  };
  const handleCronChange = (e) => {
    onChange && onChange({ ...schedule, cron: e.target.value });
  };

  // Dummy next run summary
  const nextRunSummary = schedule.type === "recurring"
    ? `Next run: (calculated from cron: ${schedule.cron || "-"})`
    : "One-time trip";

  return (
    <Card className="mb-3">
      <Card.Header>
        <h5 className="mb-0">Trip Schedule</h5>
      </Card.Header>
      <Card.Body>
        <Form.Group className="mb-3">
          <Form.Label>Schedule Type</Form.Label>
          <Form.Select value={schedule.type} onChange={handleTypeChange}>
            <option value="one-time">One-time</option>
            <option value="recurring">Recurring</option>
          </Form.Select>
        </Form.Group>
        {schedule.type === "recurring" && (
          <Form.Group className="mb-3">
            <Form.Label>
              Cron Expression{' '}
              <OverlayTrigger
                placement="right"
                overlay={
                  <Tooltip id="cron-tooltip">
                    A cron expression defines the schedule for recurring trips. Example: <code>0 8 * * 1</code> means every Monday at 8am.
                  </Tooltip>
                }
              >
                <InfoCircle style={{ cursor: 'pointer' }} />
              </OverlayTrigger>
            </Form.Label>
            <Form.Control
              type="text"
              value={schedule.cron}
              onChange={handleCronChange}
              placeholder="e.g. 0 8 * * 1 (every Monday at 8am)"
            />
          </Form.Group>
        )}
        <div className="text-muted">{nextRunSummary}</div>
      </Card.Body>
    </Card>
  );
};

export default RecurringTripScheduler; 