export const ROLES = {
  ADMIN: "admin",
  FLEET_MANAGER: "fleet_manager",
  DRIVER: "driver",
  GPS_TECHNICIAN: "gps_technician",
  CUSTOMER: "customer",
};

export const PERMISSIONS = {
  MANAGE_USERS: "manage_users",
  MANAGE_SETTINGS: "manage_settings",
  VIEW_ANALYTICS: "view_analytics",
  MANAGE_CONTENT: "manage_content",
  VIEW_PROFILE: "view_profile",
  EDIT_PROFILE: "edit_profile",
  VIEW_REPORTS: "view_reports",
  FLEET_OVERSIGHT: "fleet_oversight",
  DRIVER_MANAGEMENT: "driver_management",
  VEHICLE_ASSIGNMENT: "vehicle_assignment",
  INSTALLATION_SCHEDULING: "installation_scheduling",
  DEVICE_MANAGEMENT: "device_management",
  TECHNICAL_REPORTS: "technical_reports",
  VIEW_OWN_VEHICLE: "view_own_vehicle",
  VIEW_BILLING: "view_billing",
  ADMIN_ACCESS: "admin_access",
  USER_MANAGEMENT: "user_management",
  TEAM_MANAGEMENT: "team_management",
  CLIENT_MANAGEMENT: "client_management",
  TRACK_VEHICLES: "track_vehicles",
};

// Role hierarchy: Admin > Fleet Manager > Driver/GPS Technician > Customer
export const ROLE_HIERARCHY = [
  ROLES.ADMIN,
  ROLES.FLEET_MANAGER,
  ROLES.DRIVER,
  ROLES.GPS_TECHNICIAN,
  ROLES.CUSTOMER,
];

export const ROLE_PERMISSIONS = {
  [ROLES.ADMIN]: [
    PERMISSIONS.MANAGE_USERS,
    PERMISSIONS.MANAGE_SETTINGS,
    PERMISSIONS.VIEW_ANALYTICS,
    PERMISSIONS.MANAGE_CONTENT,
    PERMISSIONS.VIEW_PROFILE,
    PERMISSIONS.EDIT_PROFILE,
    PERMISSIONS.VIEW_REPORTS,
    PERMISSIONS.FLEET_OVERSIGHT,
    PERMISSIONS.DRIVER_MANAGEMENT,
    PERMISSIONS.VEHICLE_ASSIGNMENT,
    PERMISSIONS.INSTALLATION_SCHEDULING,
    PERMISSIONS.DEVICE_MANAGEMENT,
    PERMISSIONS.TECHNICAL_REPORTS,
    PERMISSIONS.VIEW_OWN_VEHICLE,
    PERMISSIONS.VIEW_BILLING,
    PERMISSIONS.ADMIN_ACCESS,
    PERMISSIONS.USER_MANAGEMENT,
    PERMISSIONS.TEAM_MANAGEMENT,
    PERMISSIONS.CLIENT_MANAGEMENT,
    PERMISSIONS.TRACK_VEHICLES,
  ],
  [ROLES.FLEET_MANAGER]: [
    PERMISSIONS.FLEET_OVERSIGHT,
    PERMISSIONS.DRIVER_MANAGEMENT,
    PERMISSIONS.VEHICLE_ASSIGNMENT,
    PERMISSIONS.VIEW_REPORTS,
    PERMISSIONS.VIEW_PROFILE,
    PERMISSIONS.EDIT_PROFILE,
    PERMISSIONS.TRACK_VEHICLES,
  ],
  [ROLES.DRIVER]: [
    PERMISSIONS.VIEW_PROFILE,
    PERMISSIONS.EDIT_PROFILE,
    PERMISSIONS.VIEW_REPORTS,
    PERMISSIONS.VEHICLE_ASSIGNMENT,
  ],
  [ROLES.GPS_TECHNICIAN]: [
    PERMISSIONS.INSTALLATION_SCHEDULING,
    PERMISSIONS.DEVICE_MANAGEMENT,
    PERMISSIONS.TECHNICAL_REPORTS,
    PERMISSIONS.VIEW_PROFILE,
    PERMISSIONS.EDIT_PROFILE,
  ],
  [ROLES.CUSTOMER]: [
    PERMISSIONS.VIEW_OWN_VEHICLE,
    PERMISSIONS.VIEW_PROFILE,
    PERMISSIONS.EDIT_PROFILE,
    PERMISSIONS.VIEW_REPORTS,
    PERMISSIONS.VIEW_BILLING,
  ],
};

export const hasPermission = (userRole, permission) => {
  // Inherit permissions from lower roles in the hierarchy
  const roleIndex = ROLE_HIERARCHY.indexOf(userRole);
  if (roleIndex === -1) return false;
  let permissions = [];
  for (let i = roleIndex; i < ROLE_HIERARCHY.length; i++) {
    permissions = permissions.concat(ROLE_PERMISSIONS[ROLE_HIERARCHY[i]] || []);
  }
  return permissions.includes(permission);
};

export const hasAnyPermission = (userRole, permissions) => {
  return permissions.some((permission) => hasPermission(userRole, permission));
};
