import React, { useState } from "react";
import { Form, Button, Alert, Spinner } from "react-bootstrap";
import { useDispatch } from "react-redux";
import { addVehicle as addVehicleAction, setLoading, setError } from "../../../slices/vehicleSlice";
import { addVehicle } from "../../../services/vehicle.service";

const VehicleAdd = () => {
  const dispatch = useDispatch();
  const [form, setForm] = useState({
    registrationNumber: "",
    vin: "",
    make: "",
    model: "",
    year: "",
    status: "ACTIVE",
    category: "",
  });
  const [submitted, setSubmitted] = useState(false);
  const [loading, setLoadingLocal] = useState(false);
  const [error, setErrorLocal] = useState("");

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };
  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoadingLocal(true);
    setErrorLocal("");
    const vehicle = {
      ...form,
      vehicleId: `veh-${Date.now()}`,
      category: { categoryName: form.category },
    };
    try {
      const res = await addVehicle(vehicle);
      dispatch(addVehicleAction(res.data));
      setSubmitted(true);
      setForm({
        registrationNumber: "",
        vin: "",
        make: "",
        model: "",
        year: "",
        status: "ACTIVE",
        category: "",
      });
    } catch (err) {
      setErrorLocal(err?.response?.data?.message || "Failed to add vehicle");
    } finally {
      setLoadingLocal(false);
    }
  };

  return (
    <div style={{ maxWidth: 500, margin: "0 auto" }}>
      <h4 className="mb-3">Add New Vehicle</h4>
      {submitted && (
        <Alert variant="success">Vehicle added successfully!</Alert>
      )}
      {error && <Alert variant="danger">{error}</Alert>}
      <Form onSubmit={handleSubmit}>
        <Form.Group className="mb-2">
          <Form.Label>Registration Number</Form.Label>
          <Form.Control
            name="registrationNumber"
            value={form.registrationNumber}
            onChange={handleChange}
            required
          />
        </Form.Group>
        <Form.Group className="mb-2">
          <Form.Label>VIN</Form.Label>
          <Form.Control
            name="vin"
            value={form.vin}
            onChange={handleChange}
            required
          />
        </Form.Group>
        <Form.Group className="mb-2">
          <Form.Label>Make</Form.Label>
          <Form.Control
            name="make"
            value={form.make}
            onChange={handleChange}
            required
          />
        </Form.Group>
        <Form.Group className="mb-2">
          <Form.Label>Model</Form.Label>
          <Form.Control
            name="model"
            value={form.model}
            onChange={handleChange}
            required
          />
        </Form.Group>
        <Form.Group className="mb-2">
          <Form.Label>Year</Form.Label>
          <Form.Control
            name="year"
            value={form.year}
            onChange={handleChange}
            required
            type="number"
          />
        </Form.Group>
        <Form.Group className="mb-2">
          <Form.Label>Status</Form.Label>
          <Form.Select
            name="status"
            value={form.status}
            onChange={handleChange}
          >
            <option value="ACTIVE">Active</option>
            <option value="MAINTENANCE">Maintenance</option>
            <option value="INACTIVE">Inactive</option>
          </Form.Select>
        </Form.Group>
        <Form.Group className="mb-2">
          <Form.Label>Category</Form.Label>
          <Form.Control
            name="category"
            value={form.category}
            onChange={handleChange}
          />
        </Form.Group>
        <Button type="submit" className="mt-2" disabled={loading}>
          {loading ? <Spinner size="sm" animation="border" /> : "Add Vehicle"}
        </Button>
      </Form>
    </div>
  );
};

export default VehicleAdd;
