import React from "react";
import { Card } from "react-bootstrap";

const TripMap = ({ route, stops = [], playbackData = [], liveLocation, readOnly = false }) => {
  return (
    <Card className="mb-3">
      <Card.Header>
        <h5 className="mb-0">Trip Map</h5>
      </Card.Header>
      <Card.Body>
        <div className="mb-2">
          <strong>Stops:</strong> {stops.length}
        </div>
        <div className="mb-2">
          <strong>Playback Points:</strong> {playbackData.length}
        </div>
        <div className="mb-2">
          <strong>Live Location:</strong> {liveLocation ? "Yes" : "No"}
        </div>
        <div className="border rounded p-3 text-center text-muted" style={{ minHeight: 120 }}>
          Map visualization (Leaflet/Google Maps) goes here
        </div>
      </Card.Body>
    </Card>
  );
};

export default TripMap; 