import React from "react";
import { Row, Col, Alert, Card } from "react-bootstrap";
import { AuditLog } from "../../../components/common";

// Dummy data (should be imported from a shared dummyData.js in a real app)
const dummyVehicles = [
  { status: "ACTIVE" },
  { status: "MAINTENANCE" },
  { status: "ACTIVE" },
  { status: "INACTIVE" },
  { status: "ACTIVE" },
];
const dummyDocuments = [
  { status: "VALID" },
  { status: "EXPIRING_SOON" },
  { status: "EXPIRED" },
];

const totalVehicles = dummyVehicles.length;
const activeVehicles = dummyVehicles.filter(
  (v) => v.status === "ACTIVE",
).length;
const maintenanceVehicles = dummyVehicles.filter(
  (v) => v.status === "MAINTENANCE",
).length;
const expiringDocs = dummyDocuments.filter(
  (d) => d.status === "EXPIRING_SOON",
).length;

const statusCounts = ["ACTIVE", "MAINTENANCE", "INACTIVE"].map((status) => ({
  status,
  count: dummyVehicles.filter((v) => v.status === status).length,
}));

const VehicleDashboard = () => (
  <div>
    <h4 className="mb-4">Vehicle Management Dashboard</h4>
    <Row className="mb-3">
      <Col md={3}>
        <Alert variant="primary">
          Total Vehicles: <b>{totalVehicles}</b>
        </Alert>
      </Col>
      <Col md={3}>
        <Alert variant="success">
          Active: <b>{activeVehicles}</b>
        </Alert>
      </Col>
      <Col md={3}>
        <Alert variant="warning">
          Maintenance: <b>{maintenanceVehicles}</b>
        </Alert>
      </Col>
      <Col md={3}>
        <Alert variant="danger">
          Expiring Docs: <b>{expiringDocs}</b>
        </Alert>
      </Col>
    </Row>
    <Card className="mb-3">
      <Card.Body>
        <Card.Title>Status Distribution</Card.Title>
        <div style={{ height: 120 }}>
          <div className="d-flex align-items-end h-100" style={{ gap: 16 }}>
            {statusCounts.map((s, idx) => (
              <div
                key={s.status}
                className="d-flex flex-column align-items-center"
                style={{ flex: 1 }}
              >
                <div
                  style={{
                    height: `${s.count * 30}px`,
                    width: 24,
                    background: "#1976d2",
                    borderRadius: 8,
                    marginBottom: 4,
                    transition: "height 0.3s",
                  }}
                />
                <div className="text-muted" style={{ fontSize: 12 }}>
                  {s.status}
                </div>
                <div style={{ fontWeight: "bold" }}>{s.count}</div>
              </div>
            ))}
          </div>
        </div>
      </Card.Body>
    </Card>
    <AuditLog />
  </div>
);

export default VehicleDashboard;
