import React from "react";
import { Card, Button } from "react-bootstrap";
import TripMap from "./TripMap";

const RoutePlayback = ({ route, playbackData = [], onPlay, stops = [] }) => {
  return (
    <Card>
      <Card.Header>
        <h5 className="mb-0">Route Playback</h5>
      </Card.Header>
      <Card.Body>
        <div className="mb-2">
          <strong>Route:</strong> {route?.name || "-"}
        </div>
        <div className="mb-2">
          <strong>Playback Points:</strong> {playbackData.length}
        </div>
        <Button variant="primary" onClick={onPlay} disabled={!onPlay} className="mb-3">
          Play
        </Button>
        <div className="border rounded p-3 text-center text-muted" style={{ minHeight: 80 }}>
          Playback visualization (map/animation) goes here
        </div>
        <div className="mt-3">
          <TripMap route={route} stops={stops} playbackData={playbackData} />
        </div>
      </Card.Body>
    </Card>
  );
};

export default RoutePlayback; 