import { ROLE_PERMISSIONS } from "../routes/permissions";

// MOCK USER SERVICE - Profile and Permissions

const MOCK_PROFILES = [
  {
    userId: 1,
    profile: {
      firstName: "Admin",
      lastName: "User",
      phone: "1234567890",
      address: "123 Admin St",
      role: "admin",
      company: "AdminCorp",
      profilePhoto: "",
      profileCompletion: 100,
    },
  },
  {
    userId: 2,
    profile: {
      firstName: "Normal",
      lastName: "User",
      phone: "9876543210",
      address: "456 User Ave",
      role: "user",
      company: "UserInc",
      profilePhoto: "",
      profileCompletion: 80,
    },
  },
];

// Mock audit logs
const MOCK_AUDIT_LOGS = [
  {
    id: 1,
    userId: 1,
    action: "login",
    details: { ip: "127.0.0.1" },
    timestamp: Date.now() - 100000,
  },
  {
    id: 2,
    userId: 2,
    action: "profile_update",
    details: {},
    timestamp: Date.now() - 50000,
  },
];

function findProfileByUserId(userId) {
  return MOCK_PROFILES.find((p) => p.userId === userId);
}

export const getUserProfile = (userId) => {
  const found = findProfileByUserId(userId);
  if (found) {
    return Promise.resolve({ data: found.profile });
  }
  return Promise.reject({
    response: { data: { message: "Profile not found" } },
  });
};

export const updateUserProfile = (userId, data) => {
  const found = findProfileByUserId(userId);
  if (found) {
    found.profile = { ...found.profile, ...data };
    return Promise.resolve({ data: found.profile });
  }
  return Promise.reject({
    response: { data: { message: "Profile not found" } },
  });
};

export const getUserPermissions = (role) => {
  return Promise.resolve({ data: ROLE_PERMISSIONS[role] || [] });
};

export const getAuditLogs = (userId) => {
  if (userId) {
    return Promise.resolve({
      data: MOCK_AUDIT_LOGS.filter((log) => log.userId === userId),
    });
  }
  return Promise.resolve({ data: MOCK_AUDIT_LOGS });
};

export const addAuditLog = (userId, action, details = {}) => {
  const newLog = {
    id: MOCK_AUDIT_LOGS.length + 1,
    userId,
    action,
    details,
    timestamp: Date.now(),
  };
  MOCK_AUDIT_LOGS.push(newLog);
  return Promise.resolve({ data: newLog });
};
