import React, { useState } from "react";
import { Button, Modal, Container, Row, Col, Card } from "react-bootstrap";
import TripList from "./TripList";
import TripForm from "./TripForm";
import TripDetails from "./TripDetails";
import TripAnalytics from "./TripAnalytics";
import TripPermissions from "./TripPermissions";
import TripAlertsPanel from "./TripAlertsPanel";
import VehicleForecast from "./VehicleForecast";

// Dummy trip data
const dummyTrips = [
  {
    id: 1,
    title: "Delhi to Mumbai Delivery",
    description: "Urgent delivery of electronics from Delhi to Mumbai.",
    createdBy: { id: 1, name: "Development Team", type: "team" },
    permissions: ["team_create", "edit", "view"],
    vehicle: { id: 1, name: "Truck 101", status: "AVAILABLE" },
    driver: { id: 1, name: "John Doe", location: { lat: 28.61, lng: 77.23 } },
    source: { name: "Delhi Warehouse", address: "Delhi, India", lat: 28.61, lng: 77.23, partyInfo: "Acme Corp" },
    destination: { name: "Mumbai Hub", address: "Mumbai, India", lat: 19.07, lng: 72.87, partyInfo: "Beta Solutions" },
    stops: [
      { id: 1, name: "Agra Stop", address: "Agra, India", lat: 27.18, lng: 78.01, scheduledTime: "2024-06-01T10:00", actualTime: null },
      { id: 2, name: "Surat Stop", address: "Surat, India", lat: 21.17, lng: 72.83, scheduledTime: "2024-06-01T18:00", actualTime: null },
    ],
    route: { id: 1, name: "Delhi-Mumbai Route", waypoints: [], optimized: true },
    playback: { available: true, data: [] },
    liveLocation: { lat: 24.5, lng: 75.0, timestamp: "2024-06-01T12:00" },
    analytics: {
      distance: 1400,
      duration: 24,
      speedStats: { avg: 60, max: 90, overspeedEvents: [] },
      alerts: [
        { type: "overspeeding", message: "Driver exceeded speed limit.", timestamp: "2024-06-01T11:00" },
        { type: "geo fencing breach", message: "Vehicle left geofenced area.", timestamp: "2024-06-01T11:30" },
      ],
    },
    status: "LIVE",
    schedule: { type: "one-time", cron: "", nextRun: null },
    tags: ["electronics", "urgent"],
    instant: false,
    autoCreated: false,
    createdAt: "2024-05-31T09:00",
    updatedAt: "2024-06-01T12:00",
  },
  // Add more dummy trips as needed
];

const TripManagementPage = () => {
  const [trips, setTrips] = useState(dummyTrips);
  const [showForm, setShowForm] = useState(false);
  const [editingTrip, setEditingTrip] = useState(null);
  const [selectedTrip, setSelectedTrip] = useState(null);
  const [showDetails, setShowDetails] = useState(false);
  // Permissions state for TripForm modal
  const [formPermissions, setFormPermissions] = useState([]);
  // Alerts state for TripDetails modal
  const [detailsAlerts, setDetailsAlerts] = useState([]);

  const handleCreateTrip = () => {
    setEditingTrip(null);
    setFormPermissions([]);
    setShowForm(true);
  };
  const handleEditTrip = (trip) => {
    setEditingTrip(trip);
    setFormPermissions(trip.permissions || []);
    setShowForm(true);
  };
  const handleViewTrip = (trip) => {
    setSelectedTrip(trip);
    setShowDetails(true);
    setDetailsAlerts(trip.analytics?.alerts || []);
  };
  const handleFormClose = () => {
    setShowForm(false);
    setEditingTrip(null);
    setFormPermissions([]);
  };
  const handleSaveTrip = (tripData) => {
    if (editingTrip) {
      setTrips((prev) =>
        prev.map((t) =>
          t.id === editingTrip.id
            ? { ...t, ...tripData, permissions: formPermissions, id: editingTrip.id }
            : t
        )
      );
    } else {
      const newId = Math.max(0, ...trips.map((t) => t.id)) + 1;
      setTrips((prev) => [
        ...prev,
        {
          ...tripData,
          permissions: formPermissions,
          id: newId,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
        },
      ]);
    }
    setShowForm(false);
    setEditingTrip(null);
    setFormPermissions([]);
  };
  const handleDetailsClose = () => {
    setShowDetails(false);
    setSelectedTrip(null);
    setDetailsAlerts([]);
  };
  // Dummy acknowledge handler for alerts
  const handleAcknowledgeAlert = (alert) => {
    setDetailsAlerts((prev) => prev.filter((a) => a !== alert));
  };

  return (
    <Container fluid className="py-4">
      <Row className="mb-4 align-items-center justify-content-between">
        <Col><h2>Trip Management</h2></Col>
        <Col className="text-end">
          <Button variant="primary" onClick={handleCreateTrip}>
            + Create Trip
          </Button>
        </Col>
      </Row>
      <Row>
        <Col md={8}>
          <Card className="mb-4">
            <Card.Body>
              <TripList
                trips={trips}
                onEdit={handleEditTrip}
                onView={handleViewTrip}
              />
            </Card.Body>
          </Card>
        </Col>
        <Col md={4}>
          <Card className="mb-4">
            <Card.Body>
              <TripAnalytics trips={trips} />
            </Card.Body>
          </Card>
        </Col>
      </Row>
      <Modal show={showForm} onHide={handleFormClose} size="lg" centered>
        <Modal.Header closeButton>
          <Modal.Title>{editingTrip ? "Edit Trip" : "Create Trip"}</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <TripForm
            initialData={editingTrip}
            onSave={handleSaveTrip}
            onCancel={handleFormClose}
          />
          <div className="mt-4">
            <TripPermissions
              permissions={formPermissions}
              onChange={setFormPermissions}
            />
          </div>
        </Modal.Body>
      </Modal>
      <Modal show={showDetails} onHide={handleDetailsClose} size="lg" centered>
        <Modal.Header closeButton>
          <Modal.Title>Trip Details</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <TripDetails trip={selectedTrip} onClose={handleDetailsClose} />
          <div className="mt-4">
            <TripAlertsPanel
              alerts={detailsAlerts}
              onAcknowledge={handleAcknowledgeAlert}
            />
          </div>
          <div className="mt-4">
            <VehicleForecast
              vehicles={selectedTrip && selectedTrip.vehicle ? [selectedTrip.vehicle] : []}
            />
          </div>
        </Modal.Body>
      </Modal>
    </Container>
  );
};

export default TripManagementPage; 