import React, { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';
import { useLocation } from 'react-router-dom';
import { useRealTimeTracking } from '../../../hooks/useRealTimeTracking';
import { useHistoricalTracking } from '../../../hooks/useHistoricalTracking';
import { useGeofences } from '../../../hooks/useGeofences';
import MapContainer from '../../../components/MapContainer';
import VehicleList from '../../../components/VehicleList';
import GeofenceManager from '../../../components/GeofenceManager';
import AlertsPanel from '../../../components/AlertsPanel';

// Selector to get accessible vehicles based on user/team
const selectAccessibleVehicles = (state) => {
  const { user } = state.auth;
  const allVehicles = state.vehicle.vehicles || [];
  if (!user) return [];
  if (user.role === 'admin') return allVehicles.map(v => v.vehicleId);
  // For managers/drivers, filter by assigned vehicles/teams (mock logic, adjust as needed)
  return allVehicles
    .filter(v => v.assignedTo === user.id || v.teamId === user.teamId)
    .map(v => v.vehicleId);
};

const today = new Date();
const defaultDateRange = {
  start: new Date(today.getFullYear(), today.getMonth(), today.getDate(), 0, 0, 0),
  end: new Date(today.getFullYear(), today.getMonth(), today.getDate(), 23, 59, 59)
};

const VehicleTrackingPage = () => {
  const location = useLocation();
  const [tab, setTab] = useState('realtime');
  const [selectedVehicle, setSelectedVehicle] = useState('');
  const [dateRange, setDateRange] = useState(defaultDateRange);
  const [demoMode, setDemoMode] = useState(false);

  // Pre-select vehicle if passed from navigation state
  useEffect(() => {
    if (location.state && location.state.vehicleId) {
      setSelectedVehicle(location.state.vehicleId);
    }
  }, [location.state]);

  const vehicleIds = useSelector(selectAccessibleVehicles);
  const allVehicles = useSelector(state => state.vehicle.vehicles || []);
  const vehicles = allVehicles.filter(v => vehicleIds.includes(v.vehicleId));
  useRealTimeTracking(vehicleIds);
  const locations = useSelector(state => state.tracking.realTimeLocations);
  const connectionStatus = useSelector(state => state.tracking.connectionStatus);
  const trackingState = useSelector(state => state.tracking);

  // Historical tracking
  const { loading: historicalLoading, error: historicalError } = useHistoricalTracking(selectedVehicle, dateRange);
  const historicalData = useSelector(state => selectedVehicle ? state.tracking.historicalData[selectedVehicle] : null);

  // Geofencing
  const { geofences, createGeofence, updateGeofence, deleteGeofence, toggleGeofence } = useGeofences(vehicleIds);

  // Tab UI
  return (
    <div style={{ padding: '24px' }}>
      <h2 style={{ marginBottom: '16px' }}>Vehicle Tracking Dashboard</h2>
      <div style={{ display: 'flex', gap: '12px', marginBottom: '24px' }}>
        <button onClick={() => setTab('realtime')} style={{
          background: tab === 'realtime' ? '#3b82f6' : '#f3f4f6',
          color: tab === 'realtime' ? 'white' : '#111827',
          border: 'none',
          padding: '8px 20px',
          borderRadius: '6px',
          fontWeight: 500,
          cursor: 'pointer'
        }}>Real-Time</button>
        <button onClick={() => setTab('historical')} style={{
          background: tab === 'historical' ? '#3b82f6' : '#f3f4f6',
          color: tab === 'historical' ? 'white' : '#111827',
          border: 'none',
          padding: '8px 20px',
          borderRadius: '6px',
          fontWeight: 500,
          cursor: 'pointer'
        }}>Historical</button>
        <button onClick={() => setTab('geofencing')} style={{
          background: tab === 'geofencing' ? '#3b82f6' : '#f3f4f6',
          color: tab === 'geofencing' ? 'white' : '#111827',
          border: 'none',
          padding: '8px 20px',
          borderRadius: '6px',
          fontWeight: 500,
          cursor: 'pointer'
        }}>Geofencing</button>
        <button onClick={() => setTab('alerts')} style={{
          background: tab === 'alerts' ? '#3b82f6' : '#f3f4f6',
          color: tab === 'alerts' ? 'white' : '#111827',
          border: 'none',
          padding: '8px 20px',
          borderRadius: '6px',
          fontWeight: 500,
          cursor: 'pointer'
        }}>Alerts</button>
        <label style={{ marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 8 }}>
          <input type="checkbox" checked={demoMode} onChange={e => setDemoMode(e.target.checked)} />
          <span style={{ color: demoMode ? '#3b82f6' : '#888', fontWeight: 500 }}>Demo Mode</span>
        </label>
      </div>

      {tab === 'realtime' && (
        <div style={{ display: 'flex', gap: '24px' }}>
          <div style={{ flex: 2 }}>
            <MapContainer 
              vehicles={vehicles} 
              locations={locations} 
              onVehicleSelect={setSelectedVehicle}
              demoMode={demoMode}
            />
            {demoMode && <div style={{ marginTop: 16, color: '#3b82f6', fontWeight: 500 }}>Live demo: Simulated vehicle in Gujarat region</div>}
          </div>
          <div style={{ flex: 1, minWidth: '320px' }}>
            <VehicleList 
              vehicles={vehicles} 
              locations={locations} 
              onVehicleSelect={setSelectedVehicle}
            />
          </div>
        </div>
      )}

      {tab === 'historical' && (
        <div style={{ display: 'flex', gap: '24px' }}>
          <div style={{ flex: 2 }}>
            <div style={{ marginBottom: '16px' }}>
              <label style={{ fontWeight: 500, marginRight: '8px' }}>Vehicle:</label>
              <select value={selectedVehicle} onChange={e => setSelectedVehicle(e.target.value)} style={{ padding: '6px 12px', borderRadius: '4px', border: '1px solid #d1d5db' }}>
                <option value="">Select vehicle</option>
                {vehicles.map(v => (
                  <option key={v.vehicleId} value={v.vehicleId}>{v.name || v.registrationNumber || v.vehicleId}</option>
                ))}
              </select>
              <label style={{ fontWeight: 500, margin: '0 8px 0 24px' }}>Date:</label>
              <input type="date" value={dateRange.start.toISOString().slice(0,10)} onChange={e => setDateRange({ ...dateRange, start: new Date(e.target.value), end: new Date(e.target.value + 'T23:59:59') })} style={{ padding: '6px 12px', borderRadius: '4px', border: '1px solid #d1d5db' }} />
            </div>
            <MapContainer 
              vehicles={vehicles.filter(v => v.vehicleId === selectedVehicle)}
              historicalRoute={historicalData?.locations || []}
              locations={{}}
              demoMode={demoMode}
            />
            {historicalLoading && <div>Loading historical data...</div>}
            {historicalError && <div style={{ color: 'red' }}>{historicalError}</div>}
            {demoMode && <div style={{ marginTop: 16, color: '#3b82f6', fontWeight: 500 }}>Demo: Historical route playback is simulated in demo mode.</div>}
          </div>
        </div>
      )}

      {tab === 'geofencing' && (
        <div style={{ display: 'flex', gap: '24px' }}>
          <div style={{ flex: 2 }}>
            <MapContainer 
              vehicles={vehicles} 
              geofences={geofences} 
              isCreating={false}
              demoMode={demoMode}
            />
            {demoMode && <div style={{ marginTop: 16, color: '#3b82f6', fontWeight: 500 }}>Demo: Geofence creation and alerts are simulated in demo mode.</div>}
          </div>
          <div style={{ flex: 1, minWidth: '320px' }}>
            <GeofenceManager 
              vehicleIds={vehicleIds} 
              onGeofenceCreate={() => {}}
            />
          </div>
        </div>
      )}

      {tab === 'alerts' && (
        <div style={{ maxWidth: '700px' }}>
          <AlertsPanel />
          {demoMode && <div style={{ marginTop: 16, color: '#3b82f6', fontWeight: 500 }}>Demo: Alerts are simulated in demo mode.</div>}
        </div>
      )}
    </div>
  );
};

export default VehicleTrackingPage; 